// Prefix Assembler (TOKENKILLER) — S0..PAD frozen, S3 volatile last.
const PREFIX = "S0 You are the Voice/Closer-Assist. Disclose automated at call start. Never state or negotiate price. No pressure; offer human callback. Respect calling hours + DNC. Concise reasoning.\nS1 Confirm identity/address/condition/timeline; book inspection or warm-transfer. OUTPUT ONLY JSON: {outcome,inspection_slot,condition_notes,timeline,handoff_summary}.\nPAD ---- alignment pad ----";
const src = $input.first().json;
const v = { address: src.address, city: src.city, timeline: src.timeline, condition_notes: src.condition_notes };
return [{ json: { body: {
  model: $env.DEEPSEEK_MODEL,
  temperature: 0,
  max_tokens: 500,
  messages: [
    { role: 'system', content: PREFIX },
    { role: 'user',   content: JSON.stringify(v) }
  ]
}, _prefix_bytes: PREFIX.length } }];

const r = $input.first().json;
const u = r.usage || {};
const hit = u.prompt_cache_hit_tokens || 0, miss = u.prompt_cache_miss_tokens || 0;
const ratio = (hit+miss) ? hit/(hit+miss) : 0;
let t = (r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || '{}';
let out; try { out = JSON.parse(t.replace(/```json|```/g,'').trim()); } catch(e){ out = { _parse_error:true }; }
out._cache = { hit, miss, ratio: +ratio.toFixed(4), ok: ratio >= 0.97 };
if(!out._cache.ok) console.warn('TOKENKILLER: cache ratio below floor', out._cache);
return [{ json: out }];
